import{_ as a,o as t,c as l,a4 as h}from"./chunks/framework.DzJZdBQK.js";const _=JSON.parse('{"title":"写作课作业-106","description":"","frontmatter":{"date":"2021-02-25T22:37:09","title":"写作课作业-106","categories":["写作","作业","区块链小白书"],"tags":["写作","作业","区块链小白书"]},"headers":[{"level":2,"title":"2W1H","slug":"_2w1h","link":"#_2w1h","children":[{"level":3,"title":"What","slug":"what","link":"#what","children":[]}]},{"level":2,"title":"Why","slug":"why","link":"#why","children":[]},{"level":2,"title":"how","slug":"how","link":"#how","children":[]},{"level":2,"title":"知识点","slug":"知识点","link":"#知识点","children":[]},{"level":2,"title":"我的思考","slug":"我的思考","link":"#我的思考","children":[]}],"relativePath":"posts/homework/106.md","filePath":"posts/homework/106.md"}'),o={name:"posts/homework/106.md"};function i(r,e,n,s,p,c){return t(),l("div",null,[...e[0]||(e[0]=[h('<blockquote><p>《区块链小白书》之《比特币 2.什么是比特币》</p></blockquote><h2 id="_2w1h" tabindex="-1">2W1H <a class="header-anchor" href="#_2w1h" aria-label="Permalink to &quot;2W1H&quot;">​</a></h2><h3 id="what" tabindex="-1">What <a class="header-anchor" href="#what" aria-label="Permalink to &quot;What&quot;">​</a></h3><p>理解比特币最简单的方法是把他想象成一家世界银行：这家叫Bitcoin的世界银行发行了一个叫做BTC的货币。</p><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to &quot;Why&quot;">​</a></h2><p>本小节没有说明为什么可以理解为银行。</p><h2 id="how" tabindex="-1">how <a class="header-anchor" href="#how" aria-label="Permalink to &quot;how&quot;">​</a></h2><p>通过类比的方式，说比特币是一家世界银行。通过电子邮件替代书信，互联网语音替代电话的例子，来说科技发展的进程，而比特币可能就是未来银行。</p><h2 id="知识点" tabindex="-1">知识点 <a class="header-anchor" href="#知识点" aria-label="Permalink to &quot;知识点&quot;">​</a></h2><p>理解比特币最简单的方法是把他想象成一家世界银行：这家叫Bitcoin的世界银行发行了一个叫做BTC的货币。</p><p>科技发展已经给我们演示过很多次 “过去完全不可能的事情竟然就那么发生了！”</p><h2 id="我的思考" tabindex="-1">我的思考 <a class="header-anchor" href="#我的思考" aria-label="Permalink to &quot;我的思考&quot;">​</a></h2><p>科技的发展进程是在不断的降本增效，区块链降低的是信任的成本。</p><p>Bitcoin的世界银行发行了一个叫做BTC的货币，基于翻译的局限，无论是 Bitcoin 还是 BTC，在中文之中都叫 “比特币”。那么「比特币就是电子黄金」哪里不对，为什么不对？</p><hr><p>欢迎联系我</p><p>微信号 ：Crazy_Airhead</p><p>Mixin ID : 1091586</p><p>定投课堂邀请码：6DYMBFP061</p><p>李笑来写作课邀请码：38MDGFYZK8</p><p>水龙头邀请码：FDJQHJ</p>',21)])])}const u=a(o,[["render",i]]);export{_ as __pageData,u as default};
